if (element.querySelector('.cozy-sort-dropdown')) return;

var dropdown = document.createElement('select');
dropdown.className = 'cozy-sort-dropdown';
dropdown.style.cssText = 'margin-top:12px;padding:8px 12px;font-size:14px;border-radius:6px;border:1px solid #a0a0aa;background:#1f1f23;color:#efeff1;cursor:pointer;outline:none;font-family:var(--font-body);';
dropdown.innerHTML = '<option value="default">🔽 Sort by viewers (default)</option><option value="asc">☕ Lowest viewers first (cozy)</option><option value="desc">🔥 Highest viewers first</option>';

element.appendChild(dropdown);

var tower = element.parentElement.querySelector('.tw-tower');
if (!tower) return;

function parseViewerCount(text) {
  if (!text) return 0;
  text = text.replace(/[^0-9.]/g, '');
  var num = parseFloat(text);
  if (isNaN(num)) return 0;
  if (text.includes('M')) return num * 1000000;
  if (text.includes('K') || text.includes('k')) return num * 1000;
  return num;
}

function applySort() {
  var articles = Array.from(tower.querySelectorAll('article.ghbJdj'));
  if (articles.length === 0) return;

  var val = dropdown.value;
  if (val === 'default') {
    // Restore original order by re-appending in document order from saved original indices
    if (!element._originalOrder) return;
    element._originalOrder.forEach(function(idx) {
      var el = articles[idx];
      if (el && el.parentElement === tower) tower.appendChild(el);
    });
    return;
  }

  // Save original order on first sort
  if (!element._originalOrder) {
    element._originalOrder = Array.from(tower.querySelectorAll('article.ghbJdj')).map(function(a, i) { return i; });
  }

  var streamData = articles.map(function(article, index) {
    var viewerEl = article.querySelector('.tw-media-card-stat');
    var viewers = parseViewerCount(viewerEl ? viewerEl.textContent : '');
    return { el: article, viewers: viewers };
  });

  if (val === 'asc') {
    streamData.sort(function(a, b) { return a.viewers - b.viewers; });
  } else if (val === 'desc') {
    streamData.sort(function(a, b) { return b.viewers - a.viewers; });
  }

  streamData.forEach(function(item) {
    tower.appendChild(item.el);
  });
}

dropdown.addEventListener('change', applySort);

// Save original order immediately
setTimeout(function() {
  var articles = Array.from(tower.querySelectorAll('article.ghbJdj'));
  element._originalOrder = articles.map(function(a, i) { return i; });
}, 100);
